style.css:
@-moz-document domain("classicgamezone.com") {
/* Scanlines simples */
  body::after {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    background: repeating-linear-gradient(
      to bottom,
      rgba(0,0,0,0.15) 0px,
      rgba(0,0,0,0.15) 1px,
      rgba(0,0,0,0) 3px
    );
    opacity: 0.4;
    z-index: 9999;
  }

  /* Granulado */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    background-image: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR4nGNgYAAAAAMAASsJTYQAAAAASUVORK5CYII=");
    background-repeat: repeat;
    opacity: 0.12;
    z-index: 9998;
  }

  /* Aberração cromática leve */
  html {
    filter: drop-shadow(1px 0 red) drop-shadow(-1px 0 cyan);
  }

  /* Jitter VHS suave */
  body {
    animation: vhs-jitter 2.8s infinite steps(1);
  }
  @keyframes vhs-jitter {
    0%   { transform: translateX(0); }
    10%  { transform: translateX(-1px); }
    20%  { transform: translateX(1px); }
    30%  { transform: translateX(-0.5px); }
    100% { transform: translateX(0); }
  }
}
